impl FromJs for rune_motion::Phase {
    fn from_js(v: conv::Value) -> conv::Result<Self> {
        let (tag, payload) = conv::enum_tag(v, "Phase")?;
        match (tag.as_str(), payload) {
            ("Entering", _) => Ok(rune_motion::Phase::Entering),
            ("Present", _) => Ok(rune_motion::Phase::Present),
            ("Exiting", Some(p)) => Ok(rune_motion::Phase::Exiting { generation: conv::field::<u32>(p, "Phase.Exiting", "generation")? }),
            (other, _) => Err(conv::err(format!("{other:?} isn't a {} variant (or lacks its value)", "Phase"))),
        }
    }
}
impl ToJs for rune_motion::Phase {
    fn to_js(self) -> conv::Result<conv::Value> {
        #[allow(unreachable_patterns)]
        match self {
            rune_motion::Phase::Entering => conv::ToJs::to_js("Entering"),
            rune_motion::Phase::Present => conv::ToJs::to_js("Present"),
            rune_motion::Phase::Exiting { generation } => { let o = conv::object(); conv::set(o, "generation", generation.to_js()?); Ok(conv::tagged("Exiting", o)) }
            _ => Ok(conv::undefined()),
        }
    }
}

